#!/bin/bash
# Pinned, portable constant-time AES for the SWEET legacy CBC/ECB API.
set -euo pipefail
[[ "${MACHINE_CONFIG:-}" == SWEET ]] || exit 0
[[ -f libkern/crypto/corecrypto_aes.c ]] || exit 1
bearssl_sha=7bea48e5e850ab4cafbe68d3765cdaba13a86d6f
bearssl_tmp=$(mktemp -d)
trap 'rm -rf "$bearssl_tmp"' EXIT
# BearSSL's git host has been answering 502 to CI runners on both its apex and
# www virtual hosts while serving the same repository to other clients, so a
# build that could only fetch would not run at all. Try both hosts and keep the
# pinned-commit assertion when either answers; otherwise use the copy of exactly
# these staged files appended to this script, verified file by file against the
# manifest before anything is written.
git init -q "$bearssl_tmp"
bearssl_fetched=0
for bearssl_host in https://bearssl.org/git/BearSSL \
                    https://www.bearssl.org/git/BearSSL; do
    if git -C "$bearssl_tmp" fetch -q --depth 1 "$bearssl_host" "$bearssl_sha"; then
        echo "fetched BearSSL from $bearssl_host"
        bearssl_fetched=1
        break
    fi
    echo "warning: BearSSL fetch failed from $bearssl_host" >&2
done
if [[ "$bearssl_fetched" == 1 ]]; then
git -C "$bearssl_tmp" checkout -q FETCH_HEAD
[[ "$(git -C "$bearssl_tmp" rev-parse HEAD)" == "$bearssl_sha" ]]
python3 - "$bearssl_tmp" <<'PY'
from pathlib import Path
import shutil
import sys

source = Path(sys.argv[1])
target = Path('libkern/crypto/sweet_bearssl')
if target.exists():
    raise SystemExit(f'refusing to overwrite existing AES source: {target}')
shutil.copytree(source / 'inc', target / 'inc')
(target / 'src/symcipher').mkdir(parents=True)
for file in ('inner.h', 'config.h'):
    shutil.copy2(source / 'src' / file, target / 'src' / file)
# XNU exports machine/limits.h instead of the userspace limits.h.
header = target / 'src/inner.h'
text = header.read_text()
assert text.count('#include <limits.h>') == 1
header.write_text(text.replace('#include <limits.h>',
    '#if defined(KERNEL)\n#include <machine/limits.h>\n'
    '#else\n#include <limits.h>\n#endif'))
for name in ('aes_ct', 'aes_ct_enc', 'aes_ct_dec', 'aes_ct_cbcenc', 'aes_ct_cbcdec'):
    shutil.copy2(source / 'src/symcipher' / (name + '.c'),
                 target / 'src/symcipher' / (name + '.c'))
# MD5, SHA-1 and SHA-384/512 for the legacy hash APIs, with their codecs.
for name in ('hash/md5.c', 'codec/dec32le.c', 'codec/enc32le.c',
             'hash/sha1.c', 'codec/dec32be.c', 'codec/enc32be.c',
             'hash/sha2big.c', 'codec/dec64be.c', 'codec/enc64be.c'):
    (target / 'src' / name).parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source / 'src' / name, target / 'src' / name)
shutil.copy2(source / 'LICENSE.txt', target / 'LICENSE.txt')
PY
echo "Staged BearSSL portable AES, MD5, SHA-1 and SHA-384/512 ($bearssl_sha) for SWEET"
else
python3 - "$0" "$bearssl_sha" <<'VENDPY'
import base64, hashlib, io, pathlib, sys, tarfile

script, want_sha = pathlib.Path(sys.argv[1]), sys.argv[2]
text = script.read_text()
manifest = {}
for line in text.split("__SWEET_BEARSSL_MANIFEST__\n", 1)[1].split(
        "\n__SWEET_BEARSSL_BLOB__", 1)[0].splitlines():
    if line.strip():
        digest, _, name = line.partition("  ")
        manifest[name.strip()] = digest.strip()
blob = text.split("__SWEET_BEARSSL_BLOB__\n", 1)[1].split(
    "\n__SWEET_BEARSSL_END__", 1)[0]
tar = tarfile.open(fileobj=io.BytesIO(base64.b64decode("".join(blob.split()))))
target = pathlib.Path("libkern/crypto/sweet_bearssl")
if target.exists():
    raise SystemExit("refusing to overwrite existing AES source: %s" % target)
import os
seen = set()
for m in tar.getmembers():
    if not m.isfile():
        continue
    name = m.name[2:] if m.name.startswith("./") else m.name
    name = os.path.normpath(name)
    seen.add(name)
    data = tar.extractfile(m).read()
    want = manifest.get(name)
    if want is None or want != hashlib.sha256(data).hexdigest():
        raise SystemExit("vendored BearSSL hash mismatch: %s" % name)
if seen != set(manifest):
    raise SystemExit("vendored BearSSL set differs from manifest: %s" %
                     (seen ^ set(manifest)))
target.mkdir(parents=True, exist_ok=True)
for m in tar.getmembers():
    if not m.isfile():
        continue
    name = os.path.normpath(m.name[2:] if m.name.startswith("./") else m.name)
    dst = target / name
    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_bytes(tar.extractfile(m).read())
print("SWEET: staged BearSSL from the vendored copy of commit " + want_sha)
VENDPY
	[[ -f libkern/crypto/sweet_bearssl/LICENSE.txt ]]
	[[ -f libkern/crypto/sweet_bearssl/src/symcipher/aes_ct.c ]]
	[[ -f libkern/crypto/sweet_bearssl/src/hash/sha2big.c ]]
fi

exit 0

